from pathlib import Path
p=Path('/mnt/data/round53_work')

# governance_service.py
fp=p/'governance_service.py'; s=fp.read_text()
if 'def ensure_operations_lab_schema' not in s:
    addition = '''\n\ndef ensure_operations_lab_schema(conn) -> None:\n    """Create persistent operator-lab structures used by Simulation and Training."""\n    conn.execute("""CREATE TABLE IF NOT EXISTS simulation_scenarios (\n        key TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',\n        severity TEXT NOT NULL DEFAULT 'medium', recommended_action TEXT NOT NULL DEFAULT '',\n        acceptance_json TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL\n    )""")\n    conn.execute("""CREATE TABLE IF NOT EXISTS training_attempts (\n        id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER REFERENCES admin_users(id),\n        scenario_key TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, passed INTEGER NOT NULL DEFAULT 0,\n        answer TEXT NOT NULL DEFAULT '', misses_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL\n    )""")\n    conn.execute("CREATE INDEX IF NOT EXISTS idx_training_attempts_admin ON training_attempts(admin_id, created_at DESC)")\n    conn.execute("CREATE INDEX IF NOT EXISTS idx_training_attempts_scenario ON training_attempts(scenario_key, created_at DESC)")\n    now = _now()\n    scenarios = [\n        ("payment_outage","Payment outage","Provider unavailable or callbacks delayed.","critical","Fail safely; do not double-charge; reconcile provider state.",["do not refund blindly","check provider state","reconcile before retry"]),\n        ("stockout","Stockout","Demand exhausts inventory while reservations exist.","high","Stop uncontrolled selling; inspect reservations; resolve discrepancy.",["stop uncontrolled selling","inspect reservation state","record exception"]),\n        ("refund_surge","Refund surge","Refund volume spikes above normal operating envelope.","high","Protect cash flow; enforce approval policy; reconcile provider state.",["follow approval policy","check provider refund state","reconcile before retry"]),\n        ("coupon_abuse","Coupon abuse","Promotion usage exhibits suspicious concentration or repeated redemption.","high","Preserve evidence; restrict safely; escalate suspicious activity.",["preserve evidence","do not silently edit financial history","escalate suspicious activity"]),\n    ]\n    for row in scenarios:\n        conn.execute("INSERT OR IGNORE INTO simulation_scenarios(key,title,description,severity,recommended_action,acceptance_json,updated_at) VALUES(?,?,?,?,?,?,?)", (*row[:5], _json(row[5]), now))\n    conn.commit()\n\ndef simulation_catalog(conn):\n    ensure_operations_lab_schema(conn)\n    return [dict(r) for r in conn.execute("SELECT * FROM simulation_scenarios ORDER BY severity DESC, title").fetchall()]\n\ndef simulation_report(conn, run_id: int) -> dict:\n    ensure_operations_lab_schema(conn)\n    row=conn.execute("SELECT * FROM simulation_runs WHERE id=?", (int(run_id),)).fetchone()\n    if not row: return {}\n    result=json.loads(row['results_json'] or '{}'); params=json.loads(row['parameters_json'] or '{}')\n    key=str(params.get('scenario') or '')\n    scenario=conn.execute("SELECT * FROM simulation_scenarios WHERE key=?", (key,)).fetchone()\n    acceptance=json.loads(scenario['acceptance_json'] or '[]') if scenario else []\n    result.update({"run_id":int(row['id']),"status":str(row['status']),"created_at":str(row['created_at']),\n                   "admin_id":int(row['admin_id']) if row['admin_id'] else None,\n                   "scenario_title":str(scenario['title']) if scenario else key,\n                   "scenario_severity":str(scenario['severity']) if scenario else 'medium',\n                   "recommended_action":str(scenario['recommended_action']) if scenario else '',\n                   "acceptance_checks":acceptance})\n    return result\n\ndef record_training_attempt(conn, *, admin_id: int, scenario_key: str, answer: str) -> dict:\n    ensure_operations_lab_schema(conn)\n    row=conn.execute("SELECT * FROM simulation_scenarios WHERE key=?", (scenario_key,)).fetchone()\n    if not row: raise ValueError('Unknown training scenario')\n    checks=json.loads(row['acceptance_json'] or '[]'); normalized=(answer or '').strip().lower()\n    misses=[c for c in checks if c.lower() not in normalized]; score=round((len(checks)-len(misses))/len(checks)*100) if checks else 0\n    passed=1 if score>=80 else 0; created=_now()\n    ins=conn.execute("INSERT INTO training_attempts(admin_id,scenario_key,score,passed,answer,misses_json,created_at) VALUES(?,?,?,?,?,?,?)", (int(admin_id),scenario_key,score,passed,answer[:4000],_json(misses),created)); conn.commit()\n    return {"id":int(ins.lastrowid),"scenario_key":scenario_key,"score":score,"passed":bool(passed),"misses":misses,"created_at":created}\n\ndef training_report(conn, *, admin_id: int | None = None) -> dict:\n    ensure_operations_lab_schema(conn)\n    where=''; params=[]\n    if admin_id:\n        where='WHERE admin_id=?'; params=[int(admin_id)]\n    row=conn.execute(f"SELECT COUNT(*) attempts, COALESCE(AVG(score),0) avg_score, SUM(CASE WHEN passed=1 THEN 1 ELSE 0 END) passed FROM training_attempts {where}", params).fetchone()\n    return {"attempts":int(row['attempts'] or 0),"avg_score":round(float(row['avg_score'] or 0),1),"passed":int(row['passed'] or 0)}\n'''
    s=s.replace('def ensure_guardian_mastery_schema(conn) -> None:\n', addition+'\n\ndef ensure_guardian_mastery_schema(conn) -> None:\n',1)
s=s.replace('def simulate_scenario(conn, *, admin_id: int, scenario: str, scale: int = 100) -> Dict[str, Any]:\n    scale = max(1, min(int(scale), 1_000_000))', 'def simulate_scenario(conn, *, admin_id: int, scenario: str, scale: int = 100) -> Dict[str, Any]:\n    ensure_operations_lab_schema(conn)\n    scale = max(1, min(int(scale), 1_000_000))',1)
fp.write_text(s)

# schema_contract
fp=p/'schema_contract.py'; s=fp.read_text()
if 'ColumnSpec("training_attempts"' not in s:
    s=s.replace('    ColumnSpec("observability_slo_policies", "operation_pattern", "TEXT NOT NULL"),\n]', '    ColumnSpec("observability_slo_policies", "operation_pattern", "TEXT NOT NULL"),\n    ColumnSpec("simulation_scenarios", "key", "TEXT"),\n    ColumnSpec("simulation_scenarios", "acceptance_json", "TEXT NOT NULL DEFAULT \'[]\'"),\n    ColumnSpec("training_attempts", "admin_id", "INTEGER"),\n    ColumnSpec("training_attempts", "scenario_key", "TEXT NOT NULL"),\n    ColumnSpec("training_attempts", "score", "INTEGER NOT NULL DEFAULT 0"),\n    ColumnSpec("training_attempts", "passed", "INTEGER NOT NULL DEFAULT 0"),\n]')
fp.write_text(s)

# admin routes/import
fp=p/'blueprints/admin.py'; s=fp.read_text()
needle='from governance_service import (\n    request_or_validate_approval, coupon_discount_with_margin, escalate_overdue_exceptions,\n    policy_requires_approval, approve as approve_governance, reject as reject_governance, expire_pending_approvals,\n)'
replacement='from governance_service import (\n    request_or_validate_approval, coupon_discount_with_margin, escalate_overdue_exceptions,\n    policy_requires_approval, approve as approve_governance, reject as reject_governance, expire_pending_approvals,\n    ensure_operations_lab_schema, simulation_catalog, simulation_report, record_training_attempt, training_report,\n)'
s=s.replace(needle,replacement,1)
# replace simulation route
start=s.index('@admin_bp.route("/simulation-lab", methods=["GET", "POST"])')
end=s.index('@admin_bp.route("/training", methods=["GET", "POST"])',start)
sim='''@admin_bp.route("/simulation-lab", methods=["GET", "POST"])\n@login_required\n@requires_permission("analytics.view")\ndef admin_simulation_lab():\n    conn=db.get_db(); ensure_operations_lab_schema(conn)\n    result=None; report=None\n    if request.method=="POST":\n        check_csrf(); scenario=(request.form.get("scenario") or "payment_outage").strip()\n        try:\n            from governance_service import simulate_scenario\n            result=simulate_scenario(conn,admin_id=int(session["admin_id"]),scenario=scenario,scale=int(request.form.get("scale","100")))\n            report=simulation_report(conn,int(result["id"]))\n            flash("Simulation completed. No real orders, payments, or inventory were changed.","success")\n        except (ValueError,TypeError) as exc: flash(str(exc),"error")\n    runs=conn.execute("SELECT id,label,parameters_json,results_json,status,created_at FROM simulation_runs ORDER BY created_at DESC LIMIT 30").fetchall()\n    catalog=simulation_catalog(conn); conn.close()\n    return render_template("admin/simulation_lab.html",result=result,report=report,runs=runs,catalog=catalog,scenarios=[c["key"] for c in catalog])\n\n@admin_bp.route("/simulation-lab/runs/<int:run_id>", methods=["GET"])\n@login_required\n@requires_permission("analytics.view")\ndef admin_simulation_report(run_id):\n    conn=db.get_db(); report=simulation_report(conn,run_id); conn.close()\n    if not report: abort(404)\n    return jsonify(report)\n\n'''
s=s[:start]+sim+s[end:]
# replace training route
start=s.index('@admin_bp.route("/training", methods=["GET", "POST"])')
end=s.index('@admin_bp.route("/customers/<int:customer_id>/timeline"',start)
train='''@admin_bp.route("/training", methods=["GET", "POST"])\n@login_required\n@requires_permission("tickets.create")\ndef admin_training():\n    conn=db.get_db(); ensure_operations_lab_schema(conn)\n    scenarios=[\n      {"id":"double_charge","title":"Customer reports a double charge","prompt":"A customer says their card was charged twice but only one order appears in the store.","best":["check provider payment IDs","reconcile","do not refund blindly"]},\n      {"id":"late_delivery","title":"Delivery is late","prompt":"An order has passed its expected delivery window. What is the first operational step?","best":["check fulfillment","check latest delivery event","give customer concrete status"]},\n      {"id":"negative_stock","title":"Inventory goes negative","prompt":"The dashboard reports negative inventory for a product. What should happen next?","best":["stop uncontrolled selling","investigate reservation/commit history","record exception"]},\n      {"id":"refund_request","title":"Large refund request","prompt":"A customer requests a very large refund. What should happen before money moves?","best":["verify order and provider state","follow approval policy","do not duplicate refund"]},\n    ]\n    score=None; attempt=None\n    if request.method=="POST":\n        check_csrf(); sid=request.form.get("scenario") or "double_charge"; answer=(request.form.get("answer") or "").strip(); rubric=next((x for x in scenarios if x["id"]==sid),None)\n        if rubric:\n            score=round(sum(1 for k in rubric["best"] if k in answer.lower())/len(rubric["best"])*100)\n            mapping={"double_charge":"payment_outage","late_delivery":"stockout","negative_stock":"stockout","refund_request":"refund_surge"}\n            attempt=record_training_attempt(conn,admin_id=int(session["admin_id"]),scenario_key=mapping.get(sid,"payment_outage"),answer=answer)\n            flash(f"Training exercise scored {score}/100. Attempt #{attempt['id']} recorded.","success")\n    recent=conn.execute("SELECT t.*,a.username admin_username FROM training_attempts t LEFT JOIN admin_users a ON a.id=t.admin_id ORDER BY t.created_at DESC LIMIT 50").fetchall()\n    summary=training_report(conn,admin_id=int(session["admin_id"])); conn.close()\n    return render_template("admin/training.html",scenarios=scenarios,score=score,attempt=attempt,recent=recent,summary=summary)\n\n@admin_bp.route("/training/report", methods=["GET"])\n@login_required\n@requires_permission("tickets.create")\ndef admin_training_report():\n    conn=db.get_db(); report=training_report(conn); conn.close(); return jsonify(report)\n\n'''
s=s[:start]+train+s[end:]
fp.write_text(s)

# templates
(p/'templates/admin/simulation_lab.html').write_text('''{% extends "admin/base.html" %}\n{% block title %}Simulation Lab{% endblock %}\n{% block content %}<div class="admin-topbar"><div><h1>Simulation Lab</h1><p>Stress-test operational decisions without touching real money, orders or inventory.</p></div></div><section class="card-box"><div class="dash-grid">{% for c in catalog %}<article class="card-box"><h3>{{ c.title }}</h3><p>{{ c.description }}</p><div class="status-pill">{{ c.severity|upper }}</div><p><strong>Recommended:</strong> {{ c.recommended_action }}</p><p><strong>Acceptance checks:</strong> {{ c.acceptance_json|safe }}</p></article>{% endfor %}</div></section><section class="card-box"><form method="POST" style="display:grid;gap:1rem;max-width:560px"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><label>Scenario<select name="scenario" class="admin-select">{% for s in scenarios %}<option value="{{ s }}">{{ s|replace('_',' ')|title }}</option>{% endfor %}</select></label><label>Scale<input class="admin-input" type="number" name="scale" min="1" max="1000000" value="100"></label><button class="admin-btn admin-btn--primary" type="submit">Run simulation</button></form>{% if report %}<div class="flash flash--success" style="margin-top:1rem"><strong>{{ report.scenario_title }}</strong> · {{ report.status }} · Risk {{ report.risk }} · {{ report.failed_orders }} failures · {{ report.refunds }} refunds · Net ₹{{ '{:,}'.format(report.net_amount) }}<br><strong>Recommended action:</strong> {{ report.recommended_action }}</div>{% endif %}</section><section class="card-box"><h3>Recent simulations</h3><div class="table-wrap"><table class="admin-table"><thead><tr><th>When</th><th>Scenario</th><th>Status</th><th>Report</th></tr></thead><tbody>{% for r in runs %}<tr><td>{{ r.created_at }}</td><td>{{ r.label }}</td><td>{{ r.status }}</td><td><a href="{{ url_for('admin.admin_simulation_report', run_id=r.id) }}">View</a></td></tr>{% else %}<tr><td colspan="4">No simulations yet.</td></tr>{% endfor %}</tbody></table></div></section>{% endblock %}\n''')
(p/'templates/admin/training.html').write_text('''{% extends "admin/base.html" %}\n{% block title %}Staff Training{% endblock %}\n{% block content %}<div class="admin-topbar"><div><h1>Training Mode</h1><p>Practice difficult cases without touching real customers or money.</p></div></div><section class="card-box"><strong>Your history:</strong> {{ summary.attempts }} attempts · average {{ summary.avg_score }}/100 · {{ summary.passed }} passed</section><div class="dash-grid">{% for s in scenarios %}<section class="card-box"><h3>{{ s.title }}</h3><p>{{ s.prompt }}</p><form method="POST"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><input type="hidden" name="scenario" value="{{ s.id }}"><textarea class="admin-input" name="answer" rows="5" required placeholder="Describe exactly what you would do…"></textarea><button class="admin-btn admin-btn--primary" type="submit">Submit answer</button></form><details style="margin-top:1rem"><summary>Show safe playbook</summary><ul>{% for step in s.best %}<li>{{ step|capitalize }}</li>{% endfor %}</ul></details></section>{% endfor %}</div>{% if attempt %}<section class="card-box"><h3>Latest attempt #{{ attempt.id }}</h3><p>Score <strong>{{ attempt.score }}/100</strong> · {% if attempt.passed %}PASS{% else %}RETRY{% endif %}</p>{% if attempt.misses %}<p><strong>Missed:</strong> {{ attempt.misses|join(', ') }}</p>{% endif %}</section>{% endif %}<section class="card-box"><h3>Recent attempts</h3><div class="table-wrap"><table class="admin-table"><thead><tr><th>When</th><th>Staff</th><th>Scenario</th><th>Score</th><th>Status</th></tr></thead><tbody>{% for r in recent %}<tr><td>{{ r.created_at }}</td><td>{{ r.admin_username or 'Admin' }}</td><td>{{ r.scenario_key|replace('_',' ')|title }}</td><td>{{ r.score }}/100</td><td>{{ 'Passed' if r.passed else 'Needs review' }}</td></tr>{% else %}<tr><td colspan="5">No attempts yet.</td></tr>{% endfor %}</tbody></table></div></section>{% endblock %}\n''')

# acceptance script
(p/'scripts/round53_pd_closure.py').write_text('''from pathlib import Path\nimport ast, sqlite3, sys\nsrc=Path(__file__).resolve().parents[1]\nfor f in src.rglob("*.py"):\n    ast.parse(f.read_text(encoding="utf-8"))\nsys.path.insert(0,str(src))\nimport governance_service as gs\nconn=sqlite3.connect(":memory:"); conn.row_factory=sqlite3.Row\nconn.executescript("CREATE TABLE admin_users(id INTEGER PRIMARY KEY, username TEXT, is_active INTEGER DEFAULT 1); CREATE TABLE simulation_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER, label TEXT, parameters_json TEXT, results_json TEXT, status TEXT, created_at TEXT);")\ngs.ensure_operations_lab_schema(conn)\nassert len(gs.simulation_catalog(conn))==4\nr=gs.simulate_scenario(conn, admin_id=1, scenario="payment_outage", scale=1000)\nrep=gs.simulation_report(conn,r["id"])\nassert rep["risk"]=="critical" and rep["acceptance_checks"]\natt=gs.record_training_attempt(conn, admin_id=1, scenario_key="payment_outage", answer="check provider state; reconcile before retry; do not refund blindly")\nassert att["passed"] and att["score"]==100\nsummary=gs.training_report(conn, admin_id=1)\nassert summary["attempts"]==1 and summary["passed"]==1\nprint("ROUND53_PD_CLOSURE_PASS")\n''')
(p/'ROUND53_PD_CLOSURE.md').write_text('# TITAN Round 53 — PD Closure\n\nClosed Simulation Lab and Staff Training Mode at engineering/acceptance level.\n\nSimulation Lab: persistent scenario catalog, acceptance criteria, detailed reports, report API, admin catalog/history.\n\nStaff Training: durable attempts, deterministic scoring, pass threshold, missed competencies, staff history, report API.\n\nLive browser/device and production certification remain separate.\n')
